// 打包：费用优先，同费用按交易标识字典序，选入后继续考虑账户后续序号，
// 直到上限；没有可选交易时返回空块。
func TestPackingOrder(t *testing.T) {
	vals, privs := genValidators(t, 4)
	node := openTest(t, 1, vals, 3)
	a, pa := vals[0], privs[0]
	b, pb := vals[1], privs[1]

