	// 期望顺序：B1(20)、A1(10)、A2(5)。
	txA1 := makeTx(t, pa, a, 1, 10, 5, "a1")
	txA2 := makeTx(t, pa, a, 2, 5, 5, "a2")
	txB1 := makeTx(t, pb, b, 1, 20, 5, "b1")
