	for i := 0; i < 3; i++ {
		if _, err := node.Vote(vals[i], 2, b2.ID()); err != nil {
			t.Fatal(err)
		}
	}
	if node.Height() != 2 || node.Round() != 3 {
		t.Fatalf("height/round = %d/%d, want 2/3", node.Height(), node.Round())
	}
}

// 主动结束未确认轮次：不留下确认块，原提议交易回到排队状态，轮次推进。
