	vals, _ := genValidators(t, 5)
	n1 := openTest(t, 1, vals, 3)
	n2 := openTest(t, 2, vals, 3)
	p1 := n1.Proposer()
	p2 := n2.Proposer()
	// 不同种子下首轮出块者可能相同，但多轮顺序应不同；
	// 这里验证洗牌顺序确实被种子改变（至少有一轮不同）。
	diff := false
	for i := 0; i < 5; i++ {
		if !bytes.Equal(n1.Proposer(), n2.Proposer()) {
			diff = true
		}
		_ = n1.EndRound()
		_ = n2.EndRound()
	}
	if !diff {
